#[async_trait::async_trait]
impl carbon_core::clickhouse::BatchCommit for WavebreakInstructionRow {
    async fn batch_commit(
        &self,
        client: &clickhouse::Client,
        rows: &[Self],
    ) -> carbon_core::error::CarbonResult<()> {
        macro_rules! commit_branch {
            ($variant:ident, $row:ty) => {
                if let Self::$variant(source) = self {
                    let branch_rows: Vec<$row> = rows
                        .iter()
                        .filter_map(|row| match row {
                            Self::$variant(row) => Some(row.clone()),
                            _ => None,
                        })
                        .collect();
                    return <$row as carbon_core::clickhouse::Insert>::insert(
                        source,
                        client,
                        &branch_rows,
                    )
                    .await;
                }
            };
        }

        commit_branch!(AuthorityConfigGrant, AuthorityConfigGrantRow);
        commit_branch!(AuthorityConfigInitialize, AuthorityConfigInitializeRow);
        commit_branch!(AuthorityConfigRevoke, AuthorityConfigRevokeRow);
        commit_branch!(BondingCurveClose, BondingCurveCloseRow);
        commit_branch!(BondingCurveCollectFees, BondingCurveCollectFeesRow);
        commit_branch!(BondingCurveGraduate, BondingCurveGraduateRow);
        commit_branch!(BondingCurveInitialize, BondingCurveInitializeRow);
        commit_branch!(CreateLaunch, CreateLaunchRow);
        commit_branch!(CreateLockedlaunch, CreateLockedlaunchRow);
        commit_branch!(CreatePresale, CreatePresaleRow);
        commit_branch!(GraduateManual, GraduateManualRow);
        commit_branch!(GraduateWhirlpool, GraduateWhirlpoolRow);
        commit_branch!(LpHarvest, LpHarvestRow);
        commit_branch!(LpTakeover, LpTakeoverRow);
        commit_branch!(LpTransfer, LpTransferRow);
        commit_branch!(MintConfigClose, MintConfigCloseRow);
        commit_branch!(MintConfigInitialize, MintConfigInitializeRow);
        commit_branch!(MintConfigUpdate, MintConfigUpdateRow);
        commit_branch!(PermissionConfigClose, PermissionConfigCloseRow);
        commit_branch!(PermissionConfigInitialize, PermissionConfigInitializeRow);
        commit_branch!(PermissionConfigUpdate, PermissionConfigUpdateRow);
        commit_branch!(PermissionConsumeCpi, PermissionConsumeCpiRow);
        commit_branch!(PermissionConsumeTopLevel, PermissionConsumeTopLevelRow);
        commit_branch!(PermissionRefund, PermissionRefundRow);
        commit_branch!(PermissionRevoke, PermissionRevokeRow);
        commit_branch!(ReservedAuthorityConfigA, ReservedAuthorityConfigARow);
        commit_branch!(ReservedAuthorityConfigB, ReservedAuthorityConfigBRow);
        commit_branch!(ReservedAuthorityConfigC, ReservedAuthorityConfigCRow);
        commit_branch!(ReservedAuthorityConfigY, ReservedAuthorityConfigYRow);
        commit_branch!(ReservedAuthorityConfigZ, ReservedAuthorityConfigZRow);
        commit_branch!(ReservedBondingCurveA, ReservedBondingCurveARow);
        commit_branch!(ReservedBondingCurveX, ReservedBondingCurveXRow);
        commit_branch!(ReservedBondingCurveY, ReservedBondingCurveYRow);
        commit_branch!(ReservedBondingCurveZ, ReservedBondingCurveZRow);
        commit_branch!(ReservedCreateA, ReservedCreateARow);
        commit_branch!(ReservedCreateB, ReservedCreateBRow);
        commit_branch!(ReservedCreateC, ReservedCreateCRow);
        commit_branch!(ReservedCreateY, ReservedCreateYRow);
        commit_branch!(ReservedCreateZ, ReservedCreateZRow);
        commit_branch!(ReservedGraduateA, ReservedGraduateARow);
        commit_branch!(ReservedGraduateB, ReservedGraduateBRow);
        commit_branch!(ReservedGraduateC, ReservedGraduateCRow);
        commit_branch!(ReservedGraduateX, ReservedGraduateXRow);
        commit_branch!(ReservedGraduateY, ReservedGraduateYRow);
        commit_branch!(ReservedGraduateZ, ReservedGraduateZRow);
        commit_branch!(ReservedLpA, ReservedLpARow);
        commit_branch!(ReservedLpB, ReservedLpBRow);
        commit_branch!(ReservedLpX, ReservedLpXRow);
        commit_branch!(ReservedLpY, ReservedLpYRow);
        commit_branch!(ReservedLpZ, ReservedLpZRow);
        commit_branch!(ReservedMintConfigA, ReservedMintConfigARow);
        commit_branch!(ReservedMintConfigB, ReservedMintConfigBRow);
        commit_branch!(ReservedMintConfigC, ReservedMintConfigCRow);
        commit_branch!(ReservedMintConfigY, ReservedMintConfigYRow);
        commit_branch!(ReservedMintConfigZ, ReservedMintConfigZRow);
        commit_branch!(ReservedPermissionA, ReservedPermissionARow);
        commit_branch!(ReservedTokenA, ReservedTokenARow);
        commit_branch!(ReservedTokenY, ReservedTokenYRow);
        commit_branch!(ReservedTokenZ, ReservedTokenZRow);
        commit_branch!(TokenBuyExactIn, TokenBuyExactInRow);
        commit_branch!(TokenBuyExactOut, TokenBuyExactOutRow);
        commit_branch!(TokenRefund, TokenRefundRow);
        commit_branch!(TokenSellExactIn, TokenSellExactInRow);
        commit_branch!(TokenSellExactOut, TokenSellExactOutRow);
        Ok(())
    }
}
